"""客服 Agent 主流程：模型选择工具 -> 执行 -> 工具结果回填模型 -> 生成回答。"""

import json

from model_client import ModelClient
from tools.bills import list_bills
from tools.medications import list_medications
from tools.patient_profile import patient_profile

TOOLS = {
    "patient_profile": patient_profile,
    "list_medications": list_medications,
    "list_bills": list_bills,
}


class CustomerServiceAgent:
    def __init__(self, model_client=None):
        self.model = model_client or ModelClient()
        self.last_result = None

    def _system_message(self):
        return {
            "role": "system",
            "content": ("你是医院客服助手。根据患者问题选择合适的工具，参数使用 patient_ref。"
                        "工具返回后用中文回答。不要编造工具未返回的信息。"),
            "tools": sorted(TOOLS),
        }

    def answer(self, user_text):
        first = self.model.send([
            self._system_message(),
            {"role": "user", "content": user_text},
        ])
        if not isinstance(first, dict) or "tool" not in first:
            return first if isinstance(first, str) else "请说明您想查询的内容。"

        name = first["tool"]
        if name not in TOOLS:
            return "暂不支持该查询。"
        arguments = first.get("arguments") or {}
        result = TOOLS[name](**arguments)
        self.last_result = result

        return self.model.send([
            self._system_message(),
            {"role": "user", "content": user_text},
            {"role": "assistant", "tool_call": {"name": name, "arguments": arguments}},
            {"role": "tool", "name": name, "content": result},
        ])
"""模型客户端：本机演示写请求日志，不访问外网。"""

import json
import os

EVIDENCE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "evidence")
REQUEST_LOG = os.path.join(EVIDENCE_DIR, "model-requests.jsonl")


class ModelClient:
    def __init__(self, log_path=None):
        self.log_path = log_path or REQUEST_LOG

    def send(self, messages):
        os.makedirs(os.path.dirname(self.log_path), exist_ok=True)
        with open(self.log_path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"event": "model_request", "messages": messages},
                                ensure_ascii=False) + "\n")
        if messages[-1]["role"] == "user":
            return {"tool": "patient_profile", "arguments": {"patient_ref": "P7"}}
        return "已为您查询。"

"""患者身份：以手机号或身份证号作为唯一键。"""

PATIENTS = {
    "P7": {"patient_id": 7001, "name": "张三丰(虚构)",
           "phone": "13900001234", "id_card": "110105199003074219"},
    "P8": {"patient_id": 7002, "name": "李四合(虚构)",
           "phone": "13800005678", "id_card": "310101198512061234"},
}

# 手机号 / 身份证号 -> patient_ref
_BY_PHONE = {p["phone"]: ref for ref, p in PATIENTS.items()}
_BY_ID_CARD = {p["id_card"]: ref for ref, p in PATIENTS.items()}

# 登录人（P7）与其已授权家属
SESSION = {"login_patient_ref": "P7", "authorized_refs": {"P7", "P8"}}


def find_by_identifier(value):
    """用手机号或身份证号定位 patient_ref；找不到返回 None。"""
    if not isinstance(value, str):
        return None
    value = value.strip()
    return _BY_PHONE.get(value) or _BY_ID_CARD.get(value)


def resolve_authorized_patient(patient_ref):
    if patient_ref not in SESSION["authorized_refs"]:
        raise PermissionError(f"当前登录身份无权访问 {patient_ref}")
    return PATIENTS[patient_ref]["patient_id"]
