from patient_store import PATIENTS

APPOINTMENTS = {
    "A12": {"patient_ref": "P7", "date": "2026-11-17", "time": "09:30",
            "department": "内科", "status": "已预约"},
    "A13": {"patient_ref": "P7", "date": "2026-11-18", "time": "14:00",
